def count_case_insensitive_occurrences(s, sub):
    if sub == '':
        return 0
    lower_s = s.lower()
    lower_sub = sub.lower()
    n = len(lower_sub)
    count = 0
    i = 0
    while i <= len(lower_s) - n:
        if lower_s[i:i + n] == lower_sub:
            count += 1
            i += n
        else:
            i += 1
    return count

def is_valid_python_identifier(s):
    keywords = {'if', 'else', 'elif', 'for', 'while', 'def', 'return', 'class', 'import', 'in',
                'not', 'and', 'or', 'True', 'False', 'None', 'break', 'continue', 'pass', 'try',
                'except', 'finally', 'with', 'as', 'lambda', 'yield'}
    if s in keywords or not s:
        return False
    if s[0].isdigit():
        return False
    allowed = set('_abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789')
    first_ok = s[0] == '_' or s[0].isalpha()
    body_ok = set(s) <= allowed
    return first_ok and body_ok

