def omega_prime_factor_count(n):
    count = 0
    m = n
    while m % 2 == 0:
        count += 1
        m //= 2
    d = 3
    while d * d <= m:
        while m % d == 0:
            count += 1
            m //= d
        d += 2
    if m > 1:
        count += 1
    return count

