def camel_to_slug(s):
    parts = re.findall('[A-Z]?[^A-Z]*', s)
    words = [p for p in parts if p]
    return '-'.join(w.lower() for w in words)

def digit_sum_persistence_base(n, b):
    if n < b:
        return 0
    total = 0
    while n > 0:
        total += n % b
        n //= b
    return 1 + digit_sum_persistence_base(total, b)

