def time_after_flight(depart_hhmm, flight_minutes, tz_offset_minutes):
    hh, mm = (int(part) for part in depart_hhmm.split(':'))
    total = hh * 60 + mm + flight_minutes + tz_offset_minutes
    day_delta = 0
    while total < 0:
        total += 1440
        day_delta -= 1
    while total >= 1440:
        total -= 1440
        day_delta += 1
    hours, minutes = divmod(total, 60)
    return (f'{hours:02d}:{minutes:02d}', day_delta)

