def subtract_months_from_date(y, m, d, n_months):
    def is_leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    def days_in_month(year, month):
        lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if month == 2 and is_leap(year):
            return 29
        return lengths[month - 1]
    remaining = n_months
    year, month = y, m
    while remaining > 0:
        month -= 1
        if month < 1:
            month = 12
            year -= 1
        remaining -= 1
    while remaining < 0:
        month += 1
        if month > 12:
            month = 1
            year += 1
        remaining += 1
    day = min(d, days_in_month(year, month))
    return (year, month, day)

def remove_elements_at_indices(lst, indices):
    result = list(lst)
    valid_indices = sorted({i for i in indices if 0 <= i < len(result)}, reverse=True)
    for idx in valid_indices:
        del result[idx]
    return result

